// Tiny procedural soundscape — wind, water, chitin and birdsong.
export class Soundscape {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.noise = null;
    this.ready = false;
    this.muted = false;
    this.zone = 'garden';
    this.nextChirp = 4;
    this.nextCricket = 2;
    this.windGain = null;
    this.droneGain = null;
    this.filter = null;
  }

  init() {
    if (this.ready) {
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    try {
      this.ctx = new AC();
    } catch (e) {
      return;
    }
    this.master = this.ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.5;
    this.master.connect(this.ctx.destination);

    // noise source (wind / rustle / bite texture)
    const len = this.ctx.sampleRate * 2;
    const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = buf.getChannelData(0);
    let last = 0;
    for (let i = 0; i < len; i++) {
      const white = Math.random() * 2 - 1;
      last = last * 0.96 + white * 0.04;
      data[i] = last * 3.2;
    }
    this.noise = buf;

    const wind = this.ctx.createBufferSource();
    wind.buffer = buf;
    wind.loop = true;
    this.filter = this.ctx.createBiquadFilter();
    this.filter.type = 'lowpass';
    this.filter.frequency.value = 700;
    this.windGain = this.ctx.createGain();
    this.windGain.gain.value = 0.045;
    wind.connect(this.filter).connect(this.windGain).connect(this.master);
    wind.start();

    // low forest drone
    this.droneGain = this.ctx.createGain();
    this.droneGain.gain.value = 0.018;
    this.droneGain.connect(this.master);
    for (const [f, g] of [[55, 0.55], [82.5, 0.32], [110.2, 0.14]]) {
      const o = this.ctx.createOscillator();
      o.type = 'sine';
      o.frequency.value = f;
      const og = this.ctx.createGain();
      og.gain.value = g;
      o.connect(og).connect(this.droneGain);
      o.start();
    }

    this.ready = true;
  }

  setMuted(m) {
    this.muted = m;
    if (this.master) {
      this.master.gain.setTargetAtTime(m ? 0 : 0.5, this.ctx.currentTime, 0.15);
    }
  }

  setZone(zoneId) {
    this.zone = zoneId;
    if (!this.ready) return;
    const freqs = { garden: 780, meadow: 640, edge: 420, deep: 260 };
    const drone = { garden: 0.014, meadow: 0.018, edge: 0.024, deep: 0.03 };
    const now = this.ctx.currentTime;
    this.filter.frequency.setTargetAtTime(freqs[zoneId] || 600, now, 2);
    this.droneGain.gain.setTargetAtTime(drone[zoneId] || 0.02, now, 2);
  }

  update(dt, zoneId, playing) {
    if (!this.ready || !playing) return;
    this.nextChirp -= dt;
    this.nextCricket -= dt;
    if (this.nextChirp <= 0) {
      this.nextChirp = 5 + Math.random() * 9;
      if (zoneId === 'garden' || zoneId === 'meadow') this.chirp();
    }
    if (this.nextCricket <= 0) {
      this.nextCricket = 2.4 + Math.random() * 4;
      if (zoneId === 'edge' || zoneId === 'deep') this.cricket();
    }
  }

  tone(freq, dur, type = 'sine', vol = 0.08, glide = null, delay = 0) {
    if (!this.ready) return;
    const ctx = this.ctx;
    const t0 = ctx.currentTime + delay;
    const o = ctx.createOscillator();
    const g = ctx.createGain();
    o.type = type;
    o.frequency.setValueAtTime(freq, t0);
    if (glide) o.frequency.exponentialRampToValueAtTime(Math.max(30, glide), t0 + dur);
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.exponentialRampToValueAtTime(vol, t0 + 0.012);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    o.connect(g).connect(this.master);
    o.start(t0);
    o.stop(t0 + dur + 0.05);
  }

  burst(dur = 0.08, vol = 0.14, freq = 1200, type = 'bandpass') {
    if (!this.ready) return;
    const ctx = this.ctx;
    const t0 = ctx.currentTime;
    const src = ctx.createBufferSource();
    src.buffer = this.noise;
    const f = ctx.createBiquadFilter();
    f.type = type;
    f.frequency.value = freq;
    f.Q.value = 0.9;
    const g = ctx.createGain();
    g.gain.setValueAtTime(vol, t0);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    src.connect(f).connect(g).connect(this.master);
    src.start(t0, Math.random() * 1.2);
    src.stop(t0 + dur + 0.02);
  }

  chirp() {
    if (!this.ready) return;
    const base = 1400 + Math.random() * 900;
    const n = 2 + Math.floor(Math.random() * 3);
    for (let i = 0; i < n; i++) {
      this.tone(base * (0.9 + Math.random() * 0.25), 0.055, 'sine', 0.018, base * 1.35, i * 0.09);
    }
  }

  cricket() {
    if (!this.ready) return;
    const t0 = this.ctx.currentTime;
    for (let i = 0; i < 3; i++) {
      this.tone(3200 + Math.random() * 400, 0.035, 'triangle', 0.012, null, i * 0.06);
    }
  }

  bite() {
    this.burst(0.07, 0.18, 1600, 'bandpass');
    this.tone(120, 0.1, 'sine', 0.05, 70);
  }

export const TAU = Math.PI * 2;

export const clamp = (v, a, b) => (v < a ? a : v > b ? b : v);
export const lerp = (a, b, t) => a + (b - a) * t;
export const invLerp = (a, b, v) => clamp((v - a) / (b - a), 0, 1);
export const dist2 = (x1, y1, x2, y2) => {
  const dx = x2 - x1, dy = y2 - y1;
  return dx * dx + dy * dy;
};
export const dist = (x1, y1, x2, y2) => Math.sqrt(dist2(x1, y1, x2, y2));

export function lerpAngle(a, b, t) {
  let d = (b - a) % TAU;
  if (d > Math.PI) d -= TAU;
  if (d < -Math.PI) d += TAU;
  return a + d * t;
}

export function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function hashStr(str) {
  let h = 2166136261 >>> 0;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

export function hexA(hex, alpha) {
  if (hex[0] !== '#') return hex;
  let h = hex.slice(1);
  if (h.length === 3) h = h[0] + h[0] + h[1] + h[1] + h[2] + h[2];
  const n = parseInt(h, 16);
  const r = (n >> 16) & 255, g = (n >> 8) & 255, b = n & 255;
  return `rgba(${r},${g},${b},${alpha})`;
}

export function mixHex(a, b, t) {
  const pa = parseInt(a.slice(1), 16), pb = parseInt(b.slice(1), 16);
  const ar = (pa >> 16) & 255, ag = (pa >> 8) & 255, ab = pa & 255;
  const br = (pb >> 16) & 255, bg = (pb >> 8) & 255, bb = pb & 255;
  const r = Math.round(lerp(ar, br, t)), g = Math.round(lerp(ag, bg, t)), bl = Math.round(lerp(ab, bb, t));
  return `#${((1 << 24) | (r << 16) | (g << 8) | bl).toString(16).slice(1)}`;
}

export function pick(rnd, arr) { return arr[(rnd() * arr.length) | 0]; }
export function between(rnd, a, b) { return a + rnd() * (b - a); }
export function easeOut(t) { return 1 - Math.pow(1 - t, 3); }
export function easeInOut(t) { return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2; }
export function fmtTime(s) {
  const m = Math.floor(s / 60);
  const sec = Math.floor(s % 60);
  return `${m}:${String(sec).padStart(2, '0')}`;
}
export function circleHit(x1, y1, r1, x2, y2, r2) {
  return dist2(x1, y1, x2, y2) < (r1 + r2) * (r1 + r2);
}
