  height: 4px;
  border-radius: 50%;
  background: var(--mint);
  box-shadow: 0 0 9px var(--mint);
}

.brand-copy {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
}

.brand-copy strong {
  font-family: var(--display);
  font-size: 14px;
  font-weight: 800;
  letter-spacing: .16em;
  line-height: 1;
  white-space: nowrap;
}

.brand-copy small {
  font-family: var(--mono);
  font-size: 7.5px;
  letter-spacing: .18em;
  color: var(--dim);
  line-height: 1;
  white-space: nowrap;
}

.chrome-actions {
  justify-self: end;
  display: flex;
  align-items: center;
  gap: 8px;
  pointer-events: auto;
}

.icon-btn {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  border: 1px solid var(--line);
  background: rgba(5, 16, 18, .35);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  display: grid;
  place-items: center;
  cursor: pointer;
  color: var(--ink-soft);
  transition: color .2s, border-color .2s, background .2s, transform .2s;
}

.icon-btn:hover {
  color: var(--ink);
  border-color: var(--line-strong);
  background: rgba(17, 42, 43, .55);
  transform: translateY(-1px);
}

.icon {
  width: 18px;
  height: 18px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.5;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.icon .thick { stroke-width: 2; }
.icon-sound .wave { opacity: 1; transition: opacity .2s; }
.icon-mute { display: none; }
body.muted .icon-sound { display: none; }
body.muted .icon-mute { display: block; }
.icon-mute { stroke-width: 1.5; }

/* ————— scoreboard ————— */

.scoreboard {
  justify-self: center;
  display: flex;
  align-items: center;
  gap: 18px;
  padding: 9px 18px 8px;
  border: 1px solid var(--line);
  background: linear-gradient(150deg, rgba(13, 35, 36, .66), rgba(4, 13, 15, .42));
  box-shadow: 0 14px 44px rgba(0, 0, 0, .17), inset 0 1px 0 rgba(255, 255, 255, .035);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-radius: 5px;
  min-width: 340px;
  pointer-events: none;
}

.score-side {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  min-width: 72px;
}

.score-side-right {
  align-items: flex-start;
}

.player-name {
  display: flex;
  align-items: center;
  gap: 6px;
  font-family: var(--mono);
  font-size: 8.5px;
  font-weight: 500;
  letter-spacing: .18em;
  color: var(--ink-soft);
  line-height: 1;
  white-space: nowrap;
}

.side-dot {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  flex: none;
}

.side-dot-you { background: var(--mint); box-shadow: 0 0 7px rgba(120, 242, 194, .85); }
.side-dot-rival { background: var(--coral); box-shadow: 0 0 7px rgba(255, 136, 116, .8); }

.score-number {
  font-family: var(--display);
  font-size: 34px;
  font-weight: 800;
  line-height: .88;
  letter-spacing: -.035em;
  margin: 5px 0 4px;
  color: var(--white);
  font-variant-numeric: tabular-nums;
  transform-origin: 50% 100%;
}

.score-side-left .score-number { color: var(--mint-bright); text-shadow: 0 0 22px rgba(120, 242, 194, .2); }
.score-side-right .score-number { color: #ffe2dc; text-shadow: 0 0 22px rgba(255, 136, 116, .16); }

.score-number.bump { animation: score-bump .42s var(--ease); }

@keyframes score-bump {
  0% { transform: scale(1); }
  32% { transform: scale(1.34); }
  100% { transform: scale(1); }
}

.pips {
  display: flex;
  gap: 3px;
  height: 3px;
}

.score-side-left .pips { justify-content: flex-end; }
.score-side-right .pips { justify-content: flex-start; }

.pips i {
  display: block;
  width: 10px;
  height: 2px;
  background: rgba(226, 255, 244, .13);
  border-radius: 2px;
  transition: background .25s, box-shadow .25s;
}

.score-side-left .pips i.on {
  background: var(--mint);
  box-shadow: 0 0 8px rgba(120, 242, 194, .65);
}

.score-side-right .pips i.on {
  background: var(--coral);
  box-shadow: 0 0 8px rgba(255, 136, 116, .55);
}

.score-center {
  width: 76px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  padding: 0 12px;
  border-left: 1px solid var(--line);
  border-right: 1px solid var(--line);
  align-self: stretch;
  justify-content: center;
}

.score-rule {
  display: none;
}

.score-mode {
  font-family: var(--mono);
  font-size: 7.5px;
  letter-spacing: .12em;
  color: var(--dim);
  white-space: nowrap;
}

.score-status {
  font-family: var(--display);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .13em;
  color: var(--ink-soft);
  max-width: 66px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  text-transform: uppercase;
}

.score-center.match-point .score-status {
  color: var(--coral);
  text-shadow: 0 0 12px rgba(255, 136, 116, .38);
}

/* ————— in-game hud ————— */

#hud {
  position: absolute;
  inset: 0;
  z-index: 15;
  pointer-events: none;
  opacity: 0;
  transition: opacity .45s var(--ease);
}

body[data-state="game"] #hud,
body[data-state="paused"] #hud,
body[data-state="over"] #hud {
  opacity: 1;
}

.announce {
  position: absolute;
  top: 45%;
  left: 50%;
  transform: translate(-50%, calc(-50% + 12px));
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  opacity: 0;
  transition: opacity .24s var(--ease), transform .32s var(--ease);
  width: min(640px, 86vw);
  z-index: 4;
}

.announce.show {
  opacity: 1;
  transform: translate(-50%, -50%);
}

.announce::before {
  content: "";
  position: absolute;
  inset: -92px -150px;
  z-index: -1;
  background: radial-gradient(ellipse at center, rgba(3, 10, 11, .6) 0%, rgba(3, 10, 11, 0) 68%);
  pointer-events: none;
}

.announce-kicker {
  font-family: var(--mono);
  font-size: 8.5px;
  font-weight: 600;
  letter-spacing: .24em;
  color: var(--dim);
  margin-bottom: 10px;
}

.announce-title {
  font-family: var(--display);
  font-size: clamp(42px, 6.2vw, 82px);
  font-weight: 800;
  line-height: .86;
  letter-spacing: -.03em;
  text-transform: uppercase;
  color: var(--white);
  text-shadow: 0 12px 54px rgba(0, 0, 0, .7);
}

.announce.is-you .announce-title { color: var(--mint-bright); text-shadow: 0 0 38px rgba(120, 242, 194, .25), 0 12px 54px rgba(0, 0, 0, .7); }
.announce.is-rival .announce-title { color: #ffd3c9; text-shadow: 0 0 38px rgba(255, 136, 116, .22), 0 12px 54px rgba(0, 0, 0, .7); }
.announce.is-point .announce-title { font-size: clamp(34px, 4.8vw, 64px); }

.announce-sub {
  margin-top: 11px;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .16em;
  color: var(--ink-soft);
  text-transform: uppercase;
}

.rally-badge {
  position: absolute;
  right: calc(32px + var(--safe-r));
  bottom: calc(21px + var(--safe-b));
  display: flex;
  align-items: baseline;
  gap: 7px;
  padding: 7px 10px;
  border: 1px solid var(--line);
  background: rgba(4, 14, 16, .42);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  border-radius: 3px;
  opacity: 0;
  transform: translateY(5px);
  transition: opacity .25s, transform .25s;
}

.rally-badge.show {
  opacity: 1;
  transform: none;
}

.rally-badge span {
  font-family: var(--mono);
  font-size: 7.5px;
  letter-spacing: .16em;
  color: var(--dim);
}

.rally-badge strong {
  font-family: var(--display);
  font-size: 17px;
  font-weight: 800;
  line-height: 1;
  color: var(--ink);
  font-variant-numeric: tabular-nums;
}

.controls-tip {
  position: absolute;
  left: calc(32px + var(--safe-l));
  bottom: calc(21px + var(--safe-b));
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 10px;
  border: 1px solid var(--line);
  background: rgba(4, 14, 16, .42);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  border-radius: 3px;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: .1em;
  color: var(--dim);
  transition: opacity .6s;
}

.controls-tip .tip-label { color: var(--ink-soft); letter-spacing: .17em; }
.controls-tip .or { color: var(--dim-2); }

.keyset {
  display: flex;
  gap: 3px;
}

kbd {
  font-family: var(--mono);
  font-size: 8px;
  line-height: 1;
  display: inline-grid;
  place-items: center;
  min-width: 17px;
  height: 17px;
  padding: 0 4px;
  color: var(--ink-soft);
  border: 1px solid rgba(209, 255, 238, .2);
  border-bottom-color: rgba(209, 255, 238, .12);
  border-radius: 2px;
  background: rgba(224, 255, 245, .045);
  letter-spacing: 0;
  font-weight: 500;
}

.controls-tip .or { margin: 0 1px; }

.touch-rails { display: none; }

/* ————— overlays / menu ————— */

.overlay {
  position: absolute;
  inset: 0;
  z-index: 40;
  opacity: 1;
  visibility: visible;
  transition: opacity .48s var(--ease), visibility 0s;
}

.overlay.is-hidden {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: opacity .48s var(--ease), visibility 0s linear .48s;
}

.menu-screen {
  overflow: hidden;
  background:
    linear-gradient(90deg, rgba(3, 9, 11, .97) 0%, rgba(3, 9, 11, .91) 30%, rgba(3, 9, 11, .68) 49%, rgba(3, 9, 11, .16) 72%, rgba(3, 9, 11, 0) 100%),
    radial-gradient(80% 80% at 70% 48%, rgba(18, 66, 65, .16), transparent 70%);
}

.menu-screen::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    linear-gradient(to right, transparent 0 49.94%, rgba(183, 255, 232, .045) 50%, transparent 50.06%),
    linear-gradient(to bottom, transparent 0 49.94%, rgba(183, 255, 232, .035) 50%, transparent 50.06%);
  opacity: .7;
}

.menu-inner {
  position: relative;
  z-index: 1;
  width: 100%;
  height: 100%;
  max-width: 1600px;
  margin: 0 auto;
  padding: calc(26px + var(--safe-t)) calc(5.4vw + var(--safe-r)) calc(20px + var(--safe-b)) calc(5.4vw + var(--safe-l));
  display: flex;
  flex-direction: column;
  overflow: auto;
  overscroll-behavior: contain;
  scrollbar-width: none;
}

.menu-inner::-webkit-scrollbar { display: none; }

.menu-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  flex: none;
}

.brand-menu .brand-mark { width: 31px; height: 31px; }
.brand-menu .brand-mark::before { height: 14px; left: 8px; }
.brand-menu .brand-mark::after { height: 14px; right: 8px; }
.brand-menu .brand-copy strong { font-size: 15px; }
.brand-menu .brand-copy small { font-size: 8px; }

.menu-meta {
  display: flex;
  align-items: center;
  gap: 20px;
  padding-top: 4px;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: .15em;
  color: var(--dim);
}

.live-dot {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: var(--ink-soft);
}

.live-dot i {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--mint);
  box-shadow: 0 0 10px rgba(120, 242, 194, .9);
  animation: live-pulse 2.4s ease-in-out infinite;
}

@keyframes live-pulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: .42; transform: scale(.72); }
}

.menu-body {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 40px;
  min-height: 0;
  padding: clamp(24px, 4vh, 56px) 0 clamp(18px, 4vh, 44px);
}

.menu-copy {
  width: min(510px, 44vw);
  flex: none;
}

.eyebrow {
  margin: 0;
  font-family: var(--mono);
  font-size: 8.5px;
  font-weight: 500;
  letter-spacing: .21em;
  line-height: 1.5;
  color: var(--dim);
  text-transform: uppercase;
}

.eyebrow span { color: var(--mint); opacity: .8; margin: 0 3px; }

.menu-copy h1 {
  margin: .22em 0 .17em;
  font-family: var(--display);
  font-weight: 900;
  font-size: clamp(74px, 9.2vw, 144px);
  line-height: .77;
  letter-spacing: -.055em;
  text-transform: uppercase;
  color: var(--white);
}

.menu-copy h1 > span {
  display: block;
  position: relative;
  z-index: 1;
}

.menu-copy h1 em {
  display: block;
  font-family: var(--serif);
  font-style: italic;
  font-weight: 400;
  font-size: .82em;
  line-height: .84;
  letter-spacing: -.052em;
  color: var(--mint);
  margin-left: -.045em;
  text-transform: none;
  text-shadow: 0 0 55px rgba(120, 242, 194, .1);
}

.lede {
  margin: 20px 0 26px;
  max-width: 39ch;
  font-family: var(--serif);
  font-size: clamp(14px, 1.16vw, 17px);
  line-height: 1.55;
  color: var(--ink-soft);
}

.setup {
  width: min(430px, 100%);
}

.field {
  margin-bottom: 13px;
}

.field-label {
  display: flex;
  align-items: baseline;
  gap: 9px;
  margin-bottom: 7px;
  font-family: var(--mono);
  font-size: 7.5px;
  font-weight: 500;
  letter-spacing: .2em;
  color: var(--dim);
}

.field-label em {
  font-style: normal;
  letter-spacing: .1em;
  color: var(--mint);
  font-size: 7px;
  opacity: .8;
}

.field-difficulty {
  transition: opacity .3s;
}

.field-difficulty.is-dim {
  opacity: .32;
  pointer-events: none;
}

.segmented {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3px;
  padding: 3px;
  border: 1px solid var(--line);
  border-radius: 3px;
  background: rgba(220, 255, 244, .025);
}

.segmented button {
  appearance: none;
  border: 0;
  border-radius: 2px;
  background: transparent;
  padding: 9px 13px 8px;
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  cursor: pointer;
  color: var(--dim);
  transition: background .2s, color .2s, box-shadow .2s;
}

.segmented button span {
  font-family: var(--display);
  font-size: 14px;
  font-weight: 800;
  letter-spacing: .08em;
}

.segmented button small {
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: .08em;
  color: var(--dim-2);
  transition: color .2s;
}

.segmented button:hover {
  background: rgba(220, 255, 244, .055);
  color: var(--ink-soft);
}

.segmented button.is-active {
  background: var(--white);
  color: #061111;
  box-shadow: 0 3px 18px rgba(0, 0, 0, .2);
}

.segmented button.is-active small { color: #526662; }

.difficulty {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

.difficulty button {
  appearance: none;
  background: transparent;
  border: 0;
  border-right: 1px solid var(--line);
  padding: 8px 5px 7px;
  font-family: var(--mono);
  font-size: 7.5px;
  letter-spacing: .12em;
  color: var(--dim);
  cursor: pointer;
  transition: color .2s, background .2s;
}

.difficulty button:last-child { border-right: 0; }
.difficulty button:hover { color: var(--ink); background: rgba(220, 255, 244, .035); }
.difficulty button.is-active { color: var(--mint); background: var(--mint-faint); }

.start-btn {
  position: relative;
  width: 100%;
  margin-top: 17px;
  padding: 16px 18px;
  border: 1px solid var(--mint);
  border-radius: 2px;
  background: var(--mint);
  color: #04100d;
  display: flex;
  align-items: center;
  justify-content: space-between;
  cursor: pointer;
  font-family: var(--display);
  font-size: 13px;
  font-weight: 900;
  letter-spacing: .16em;
  overflow: hidden;
  transition: transform .22s var(--ease), box-shadow .22s var(--ease), background .22s;
}

.start-btn::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(105deg, transparent 30%, rgba(255, 255, 255, .72) 50%, transparent 70%);
  transform: translateX(-130%);
  transition: transform .6s var(--ease);
}

.start-btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 12px 36px rgba(110, 240, 187, .16);
}

.start-btn:hover::before { transform: translateX(130%); }

.start-btn:active { transform: translateY(0); }

.start-arrow {
  font-family: var(--sans);
  font-size: 21px;
  font-weight: 400;
  line-height: .7;
  transition: transform .2s var(--ease);
}

.start-btn:hover .start-arrow { transform: translateX(4px); }

.menu-hint {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 5px;
  margin: 14px 0 0;
  font-family: var(--mono);
  font-size: 7.5px;
  letter-spacing: .07em;
  color: var(--dim);
}

.menu-hint span { margin-left: 2px; }
.menu-hint .hint-sep { margin: 0 3px; color: var(--dim-2); }
.menu-hint kbd { min-width: 16px; height: 16px; font-size: 7.5px; }

.menu-aside {
  align-self: flex-end;
  width: 158px;
  margin-bottom: 4px;
  margin-right: 1vw;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  text-align: right;
  color: var(--dim);
  opacity: .82;
}

.aside-rule {
  width: 100%;
  height: 1px;
  background: linear-gradient(to left, var(--line-strong), transparent);
  margin: 18px 0;
}

.aside-kicker,
.aside-foot {
  margin: 0;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: .16em;
  line-height: 1.7;
}

.aside-big {
  margin: 2px 0 -4px;
  font-family: var(--serif);
  font-size: 104px;
  font-style: italic;
  line-height: 1;
  color: var(--mint);
  opacity: .88;
}

.aside-copy {
  margin: 0;
  font-family: var(--serif);
  font-size: 13px;
  line-height: 1.5;
  color: var(--ink-soft);
}

.aside-motion {
  display: flex;
  align-items: center;
  gap: 10px;
  color: var(--ink-soft);
}

.motion-bar {
  width: 3px;
  height: 54px;
  border-radius: 3px;
  background: linear-gradient(to bottom, var(--mint), rgba(120, 242, 194, .1));
  box-shadow: 0 0 18px rgba(120, 242, 194, .2);
}

.motion-arrows {
  font-family: var(--mono);
  font-size: 13px;
  line-height: .85;
  color: var(--mint);
}

.menu-foot {
  flex: none;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  border-top: 1px solid var(--line);
  padding-top: 13px;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: .14em;
  color: var(--dim-2);
}

.menu-foot .foot-mid { display: flex; align-items: center; gap: 8px; color: var(--dim); }
.menu-foot .foot-mid i { width: 3px; height: 3px; border-radius: 50%; background: var(--mint); }
.menu-foot b { color: var(--mint); font-weight: 500; margin-left: 5px; }

/* ————— pause + result modals ————— */

.modal-screen {
  display: grid;
  place-items: center;
  padding: 22px;
  background: rgba(3, 10, 12, .6);
  backdrop-filter: blur(13px);
  -webkit-backdrop-filter: blur(13px);
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: opacity .34s var(--ease), visibility 0s linear .34s;
}

.modal-screen.is-open {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
  transition: opacity .34s var(--ease), visibility 0s;
}

.modal-screen.is-open .modal,
.modal-screen.is-open .end-inner {
  transform: none;
  opacity: 1;
}

.modal {
  width: min(470px, 100%);
  padding: 34px 36px 30px;
  border: 1px solid var(--line-strong);
  border-radius: 4px;
  background:
    linear-gradient(145deg, rgba(15, 38, 39, .92), rgba(5, 15, 17, .94));
  box-shadow: 0 30px 100px rgba(0, 0, 0, .48), inset 0 1px 0 rgba(255, 255, 255, .05);
  transform: translateY(12px);
  opacity: 0;
  transition: transform .36s var(--ease), opacity .36s var(--ease);
}

.modal h2 {
  margin: 10px 0 14px;
  font-family: var(--display);
  font-size: clamp(50px, 7vw, 80px);
