function predictBallY(targetX) {
  if (Math.abs(ball.vx) < 1) return court.y + court.h / 2;
  const t = (targetX - ball.x) / ball.vx;
  if (t < 0) return clamp(ball.y, court.y, court.y + court.h);
  let y = ball.y + ball.vy * t;
  const minY = court.y + ball.r;
  const maxY = court.y + court.h - ball.r;
  const span = maxY - minY;
  if (span <= 0) return court.y + court.h / 2;
  const wrapped = ((y - minY) % (span * 2) + span * 2) % (span * 2);
  y = wrapped <= span ? minY + wrapped : minY + (span * 2 - wrapped);
  return y;
}

