437:   const {
438:     vx = rand(-100, 100),
439:     vy = rand(-100, 100),
440:     life = rand(0.35, 0.8),
441:     size = rand(1, 2.6),
442:     gravity = 0,
443:     drag = 0.9,
444:     kind = 'dot',
445:     rot = rand(0, TAU),
446:     spin = rand(-6, 6),
447:   } = options;
448:   particles.push({ x, y, vx, vy, life, maxLife: life, size, color, gravity, drag, kind, rot, spin });
449:   if (particles.length > 620) particles.splice(0, particles.length - 620);
450: }
