452: function spawnSpark(x, y, color, count = 10, power = 180, direction = null) {
453:   for (let i = 0; i < count; i++) {
454:     const base = direction === null ? rand(0, TAU) : direction + rand(-0.7, 0.7);
455:     const speed = rand(power * 0.3, power);
456:     addParticle(x, y, color, {
457:       vx: Math.cos(base) * speed,
458:       vy: Math.sin(base) * speed,
459:       life: rand(0.25, 0.6),
460:       size: rand(1, 2.5),
461:       drag: 0.93,
462:       kind: Math.random() < 0.3 ? 'streak' : 'dot',
463:     });
464:   }
465: }
