467: function spawnScoreBurst(x, y, color, big = false) {
468:   addRing(x, y, color, 10, big ? 0.7 : 0.52, 2);
469:   addRing(x, y, color, 4, 0.45, 1);
470:   spawnSpark(x, y, color, big ? 42 : 28, big ? 320 : 245);
471:   for (let i = 0; i < (big ? 24 : 14); i++) {
472:     addParticle(x, y, color, {
473:       vx: rand(-210, 210),
474:       vy: rand(-210, 210),
475:       life: rand(0.45, 1.15),
476:       size: rand(1.5, 4),
477:       drag: 0.9,
478:       gravity: 90,
479:       kind: 'streak',
480:     });
481:   }
482: }
