486:   for (let i = 0; i < 90; i++) {
487:     addParticle(rand(court.x + 40, court.x + court.w - 40), court.y + rand(0, court.h * 0.2), colors[i % colors.length], {
488:       vx: rand(-130, 130),
489:       vy: rand(20, 190),
490:       life: rand(1.5, 3.2),
491:       size: rand(1.5, 4),
