500: function updateEffects(dt) {
501:   for (let i = particles.length - 1; i >= 0; i--) {
502:     const p = particles[i];
503:     p.life -= dt;
504:     if (p.life <= 0) {
505:       particles.splice(i, 1);
506:       continue;
507:     }
508:     p.x += p.vx * dt;
509:     p.y += p.vy * dt;
510:     p.vx *= Math.pow(p.drag, dt * 60);
511:     p.vy = p.vy * Math.pow(p.drag, dt * 60) + p.gravity * dt;
512:     p.rot += p.spin * dt;
513:   }
514:   for (let i = rings.length - 1; i >= 0; i--) {
515:     const r = rings[i];
516:     r.life -= dt;
517:     if (r.life <= 0) {
518:       rings.splice(i, 1);
519:       continue;
520:     }
521:     r.radius += dt * (r.radius * 3 + 60);
522:   }
523:   game.shake = Math.max(0, game.shake - dt * 30);
524:   game.flash = Math.max(0, game.flash - dt * 2.6);
525:   left.hitGlow = Math.max(0, left.hitGlow - dt * 3.5);
526:   right.hitGlow = Math.max(0, right.hitGlow - dt * 3.5);
527:   ball.hitFlash = Math.max(0, ball.hitFlash - dt * 5);
528:   ball.servePulse = (ball.servePulse + dt * 2.4) % TAU;
529: 
530:   for (const m of motes) {
531:     m.x += m.vx * dt;
532:     m.y += m.vy * dt;
533:     if (m.x < 0.02) m.x = 0.98;
534:     if (m.x > 0.98) m.x = 0.02;
535:     if (m.y < 0.02) m.y = 0.98;
536:     if (m.y > 0.98) m.y = 0.02;
537:   }
538: }
