781: function scorePoint(scorer) {
782:   if (game.state !== 'playing') return;
783:   const ace = game.rally === 0;
784:   if (scorer === 0) {
785:     game.leftScore += 1;
786:     game.leftHits += game.rally;
787:   } else {
788:     game.rightScore += 1;
789:     game.rightHits += game.rally;
790:   }
791:   game.bestRally = Math.max(game.bestRally, game.rally);
792:   game.state = 'point';
793:   game.pointTimer = 1.35;
794:   game.scoredBy = scorer;
795:   game.rally = 0;
796:   ball.visible = false;
797:   ball.vx = 0;
798:   ball.vy = 0;
799: 
800:   const wonMatch = (scorer === 0 ? game.leftScore : game.rightScore) >= POINTS_TO_WIN;
801:   const burstX = scorer === 0 ? court.x + court.w + 10 : court.x - 10;
802:   const burstY = clamp(ball.y, court.y + 14, court.y + court.h - 14);
803:   const color = scorer === 0 ? '120,242,194' : '255,136,116';
804:   spawnScoreBurst(burstX, burstY, `rgba(${color},.95)`, wonMatch);
805:   game.shake = wonMatch ? 18 : 10;
806:   game.flash = wonMatch ? 0.28 : 0.14;
807:   game.flashColor = color;
808:   sound.score(scorer === 0 ? 0 : 1);
809:   if (navigator.vibrate) navigator.vibrate(wonMatch ? [25, 40, 70] : 20);
810:   updateScoreHud(scorer);
811: 
812:   if (wonMatch) {
813:     game.pendingEnd = true;
814:     game.winner = scorer;
815:     game.positionHeld = true;
816:     game.pointTimer = 1.55;
817:     const title = game.mode === 'local'
818:       ? `P${scorer + 1} WINS`
819:       : (scorer === 0 ? 'MATCH WON' : 'MATCH LOST');
820:     showAnnounce(
821:       `${game.leftScore} — ${game.rightScore} · FINAL`,
822:       title,
823:       'THE NIGHT REMEMBERS',
824:       scorer === 0 ? 'is-you' : 'is-rival',
825:       1.5,
826:     );
827:     sound.matchPoint();
828:   } else {
829:     game.serveDir = scorer === 0 ? 1 : -1;
830:     const scorerName = playerName(scorer);
831:     const atMatchPoint = game.leftScore === POINTS_TO_WIN - 1 || game.rightScore === POINTS_TO_WIN - 1;
832:     showAnnounce(
833:       atMatchPoint ? `MATCH POINT · ${scorerName}` : `POINT · ${scorerName}`,
834:       ace ? 'ACE' : 'POINT',
835:       `${game.leftScore} — ${game.rightScore}`,
836:       scorer === 0 ? 'is-you' : 'is-rival',
837:       1.28,
838:     );
839:   }
840: }
