941: function keyAxes(side) {
942:   const upW = keys.has('KeyW');
943:   const downW = keys.has('KeyS');
944:   const upArrow = keys.has('ArrowUp');
945:   const downArrow = keys.has('ArrowDown');
946:   if (game.mode === 'local') {
947:     return side === 'left'
948:       ? { up: upW, down: downW }
949:       : { up: upArrow, down: downArrow };
950:   }
951:   return { up: upW || upArrow, down: downW || downArrow };
952: }
953: 
954: function updateHumanPaddle(p, dt) {
955:   p.prevY = p.y;
956:   const minY = court.y;
957:   const maxY = court.y + court.h - p.h;
958:   const speed = court.h * (window.innerHeight < 560 ? 1.18 : 1.03);
959: 
960:   if (p.pointerY !== null) {
961:     const center = p.y + p.h / 2;
962:     const desired = clamp(p.pointerY, court.y, court.y + court.h) - center;
963:     const maxStep = speed * 1.55 * dt;
964:     const step = clamp(desired * 0.72, -maxStep, maxStep);
965:     p.y += step;
966:     p.vy = step / Math.max(dt, 0.0001);
967:   } else {
968:     const axes = keyAxes(p.side);
969:     const direction = (axes.down ? 1 : 0) - (axes.up ? 1 : 0);
970:     const targetV = direction * speed;
971:     p.vy += (targetV - p.vy) * Math.min(1, dt * 24);
972:     p.y += p.vy * dt;
973:   }
974: 
975:   if (p.y < minY) {
976:     p.y = minY;
977:     if (p.vy < 0) p.vy = 0;
978:   } else if (p.y > maxY) {
979:     p.y = maxY;
980:     if (p.vy > 0) p.vy = 0;
981:   }
982: }
