984: function predictBallY(targetX) {
985:   if (Math.abs(ball.vx) < 1) return court.y + court.h / 2;
986:   const t = (targetX - ball.x) / ball.vx;
987:   if (t < 0) return clamp(ball.y, court.y, court.y + court.h);
988:   // Deliberately read the line, not every bank. This is what makes a human
989:   // return down the wall so dangerous, and keeps the machine beatable.
990:   return clamp(ball.y + ball.vy * t, court.y + ball.r, court.y + court.h - ball.r);
991: }
