993: function updateAi(dt) {
994:   const p = right;
995:   const profile = CPU_PROFILES[game.difficulty];
996:   p.prevY = p.y;
997:   const controlsActive = game.state === 'playing';
998:   const incoming = controlsActive && ball.vx > 0;
999: 
1000:   if (!controlsActive) {
1001:     ai.target = court.y + court.h / 2;
1002:     ai.timer = 0;
1003:   } else {
1004:     ai.timer -= dt;
1005:     if (incoming) {
1006:       if (ai.timer <= 0) {
1007:         const predicted = predictBallY(p.x - ball.r * 0.6);
1008:         const blend = lerp(ball.y, predicted, profile.anticipation);
1009:         const error = rand(-1, 1) * court.h * profile.error;
1010:         const drift = Math.sin(game.matchTime * 0.75 + 1.4) * court.h * 0.008;
1011:         const lapse = Math.random() < profile.mistake ? rand(-0.2, 0.2) * court.h : 0;
1012:         ai.target = blend + error + drift + lapse;
1013:         ai.timer = profile.reaction * rand(0.78, 1.28);
1014:       }
1015:     } else {
1016:       ai.target = court.y + court.h * 0.5 + Math.sin(game.matchTime * 0.7) * court.h * 0.05;
1017:       ai.timer = Math.max(ai.timer, 0);
1018:     }
1019:   }
1020: 
1021:   const target = clamp(ai.target, court.y + p.h * 0.5, court.y + court.h - p.h * 0.5);
1022:   const desired = target - (p.y + p.h / 2);
1023:   const responsiveness = incoming ? profile.speed : profile.speed * 0.45;
1024:   const maxStep = court.h * responsiveness * dt;
1025:   const step = clamp(desired * 7, -maxStep, maxStep);
1026:   p.y += step;
1027:   p.vy = step / Math.max(dt, 0.0001);
1028:   p.y = clamp(p.y, court.y, court.y + court.h - p.h);
1029: }
