1031: function updatePaddles(dt) {
1032:   const control = game.state === 'playing' || game.state === 'serve';
1033:   if (control) {
1034:     updateHumanPaddle(left, dt);
1035:     if (game.mode === 'local') {
1036:       updateHumanPaddle(right, dt);
1037:     } else {
1038:       updateAi(dt);
1039:     }
1040:   } else {
1041:     left.prevY = left.y;
1042:     right.prevY = right.y;
1043:     left.vy = 0;
1044:     right.vy = 0;
1045:   }
1046: }
