1050: function bounceWall(topWall) {
1051:   const y = topWall ? court.y + ball.r : court.y + court.h - ball.r;
1052:   ball.y = y;
1053:   ball.vy = topWall ? Math.abs(ball.vy) : -Math.abs(ball.vy);
1054:   const color = topWall ? 'rgba(173,255,220,.75)' : 'rgba(255,218,208,.75)';
1055:   addRing(ball.x, topWall ? court.y + 1 : court.y + court.h - 1, color, 4, 0.32, 1);
1056:   spawnSpark(ball.x, topWall ? court.y + 1 : court.y + court.h - 1, color, 6, 125, topWall ? Math.PI / 2 : -Math.PI / 2);
1057:   game.shake = Math.min(12, game.shake + 2.4);
1058:   sound.wall();
1059: }
