1061: function collidePaddle(p) {
1062:   const r = ball.r;
1063:   const isLeft = p.side === 'left';
1064:   const plane = isLeft ? p.x + p.w : p.x;
1065:   const prevEdge = isLeft ? ball.prevX - r : ball.prevX + r;
1066:   const edge = isLeft ? ball.x - r : ball.x + r;
1067: 
1068:   if (isLeft) {
1069:     if (ball.vx >= 0 || prevEdge < plane || edge > plane) return false;
1070:   } else if (ball.vx <= 0 || prevEdge > plane || edge < plane) {
1071:     return false;
1072:   }
1073: 
1074:   const denom = prevEdge - edge;
1075:   const t = denom === 0 ? 0 : clamp((prevEdge - plane) / denom, 0, 1);
1076:   const hitY = lerp(ball.prevY, ball.y, t);
1077:   if (hitY < p.y - r * 0.65 || hitY > p.y + p.h + r * 0.65) return false;
1078: 
1079:   const rel = clamp((hitY - (p.y + p.h / 2)) / (p.h / 2 + r * 0.5), -1, 1);
1080:   const direction = isLeft ? 1 : -1;
1081:   const nextSpeed = Math.min(ball.speed * 1.045 + 5, maxSpeed());
1082:   const angle = clamp(rel * 0.84 + p.vy / (court.h * 3.3), -0.94, 0.94);
1083: 
1084:   ball.speed = nextSpeed;
1085:   ball.x = isLeft ? plane + r + 0.7 : plane - r - 0.7;
1086:   ball.y = hitY;
1087:   ball.vx = direction * nextSpeed * Math.cos(angle);
1088:   ball.vy = nextSpeed * Math.sin(angle);
1089:   ball.hitFlash = 1;
1090: 
1091:   game.rally += 1;
1092:   game.bestRally = Math.max(game.bestRally, game.rally);
1093:   p.hitGlow = 1;
1094:   const color = isLeft ? 'rgba(173,255,220,.95)' : 'rgba(255,206,195,.95)';
1095:   addRing(plane, hitY, color, ball.r + 3, 0.3, 1.4);
1096:   spawnSpark(plane, hitY, color, 12, 210, isLeft ? 0 : Math.PI);
1097:   game.shake = Math.min(12, game.shake + 3.4);
1098:   game.flash = Math.max(game.flash, 0.035);
1099:   game.flashColor = isLeft ? '120,242,194' : '255,136,116';
1100:   sound.ball(rel * 0.7, nextSpeed / baseSpeed());
1101:   if (navigator.vibrate) navigator.vibrate(8);
1102:   return true;
1103: }
