1105: function updateBall(dt) {
1106:   ball.prevX = ball.x;
1107:   ball.prevY = ball.y;
1108:   ball.x += ball.vx * dt;
1109:   ball.y += ball.vy * dt;
1110: 
1111:   if (ball.y - ball.r < court.y) bounceWall(true);
1112:   else if (ball.y + ball.r > court.y + court.h) bounceWall(false);
1113: 
1114:   collidePaddle(left);
1115:   collidePaddle(right);
1116: 
1117:   if (ball.x + ball.r < court.x) {
1118:     scorePoint(1);
1119:     return;
1120:   }
1121:   if (ball.x - ball.r > court.x + court.w) {
1122:     scorePoint(0);
1123:     return;
1124:   }
1125: 
1126:   const last = ball.trail[ball.trail.length - 1];
1127:   if (!last || (last.x - ball.x) ** 2 + (last.y - ball.y) ** 2 > 9) {
1128:     ball.trail.push({ x: ball.x, y: ball.y });
1129:     if (ball.trail.length > 28) ball.trail.shift();
1130:   }
1131: }
