18:       return;
19:     }
20:     const AC = window.AudioContext || window.webkitAudioContext;
21:     if (!AC) return;
22:     try {
23:       this.ctx = new AC();
24:       this.master = this.ctx.createGain();
25:       this.master.gain.value = this.muted ? 0 : 0.52;
26:       const limiter = this.ctx.createDynamicsCompressor();
27:       limiter.threshold.value = -14;
28:       limiter.knee.value = 18;
29:       limiter.ratio.value = 5;
30:       limiter.attack.value = 0.002;
31:       limiter.release.value = 0.18;
32:       this.master.connect(limiter).connect(this.ctx.destination);
