35:       this.noiseBuffer = this.ctx.createBuffer(1, length, this.ctx.sampleRate);
36:       const data = this.noiseBuffer.getChannelData(0);
37:       for (let i = 0; i < length; i++) {
38:         data[i] = Math.random() * 2 - 1;
39:       }
40:     } catch (err) {
41:       this.ctx = null;
42:     }
43:   }
44: 
45:   resume() {
46:     if (!this.ctx) this.init();
47:     if (this.ctx && this.ctx.state === 'suspended') this.ctx.resume();
48:   }
49: 
50:   setMuted(muted) {
51:     this.muted = muted;
52:     try {
53:       localStorage.setItem('night-rally-muted', muted ? '1' : '0');
54:     } catch (err) { /* private mode */ }
55:     if (!this.master || !this.ctx) return;
56:     this.master.gain.setTargetAtTime(muted ? 0 : 0.52, this.ctx.currentTime, 0.015);
57:   }
58: 
59:   toggleMuted() {
60:     this.setMuted(!this.muted);
61:     return this.muted;
62:   }
63: 
64:   tone({
65:     freq = 440,
66:     endFreq = null,
67:     duration = 0.12,
68:     type = 'sine',
69:     volume = 0.08,
70:     attack = 0.006,
71:     delay = 0,
72:     pan = 0,
73:   } = {}) {
74:     if (!this.ctx || this.muted) return;
75:     const ctx = this.ctx;
76:     const t0 = ctx.currentTime + delay;
