78:     const gain = ctx.createGain();
79:     const panner = ctx.createStereoPanner ? ctx.createStereoPanner() : null;
80:     osc.type = type;
81:     osc.frequency.setValueAtTime(Math.max(20, freq), t0);
82:     if (endFreq) osc.frequency.exponentialRampToValueAtTime(Math.max(20, endFreq), t0 + duration);
83:     gain.gain.setValueAtTime(0.0001, t0);
