94:   }
95: 
96:   noise({ duration = 0.05, volume = 0.05, freq = 1200, q = 0.9, type = 'bandpass', delay = 0, pan = 0 } = {}) {
97:     if (!this.ctx || this.muted || !this.noiseBuffer) return;
98:     const ctx = this.ctx;
